string dir="TerrainReferences/WholeMapGradient800";
var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/Scenes/Main Game Scene.unity");
var mm=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MapMagic.Core.MapMagicObject>(true)).First();
System.Func<System.Array,byte[]> bytes=a=>{var b=new byte[a.Length*4];System.Buffer.BlockCopy(a,0,b,0,b.Length);return b;};
var records=new System.Collections.Generic.List<object>();
foreach(var t in mm.GetComponentsInChildren<Terrain>(true)){var td=t.terrainData;int n=td.heightmapResolution;var b=bytes(td.GetHeights(0,0,n,n));System.IO.File.WriteAllBytes(dir+"/After/"+td.name+".height.f32",b);if(System.IO.File.Exists(dir+"/Before/"+td.name+".alpha.f32"))System.IO.File.WriteAllBytes(dir+"/After/"+td.name+".alpha.f32",bytes(td.GetAlphamaps(0,0,td.alphamapResolution,td.alphamapResolution)));records.Add(new{name=td.name,heightHash=System.BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(b)).Replace("-", "").ToLowerInvariant()});}
var transforms=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).OrderBy(t=>t.GetInstanceID()).Select(t=>new{id=t.GetInstanceID(),p=new[]{t.position.x,t.position.y,t.position.z},q=new[]{t.rotation.x,t.rotation.y,t.rotation.z,t.rotation.w},s=new[]{t.localScale.x,t.localScale.y,t.localScale.z}}).ToArray();
string transformJson=Newtonsoft.Json.JsonConvert.SerializeObject(transforms);System.IO.File.WriteAllText(dir+"/transforms-after.json",transformJson);
var report=new{terrains=records,transformsUnchanged=transformJson==System.IO.File.ReadAllText(dir+"/transforms-before.json"),locks=Newtonsoft.Json.JsonConvert.SerializeObject(mm.locks.Select(l=>new{l.locked,l.guiName,l.relativeHeight,l.worldRadius,l.worldTransition,p=new[]{l.worldPos.x,l.worldPos.y,l.worldPos.z}})),auto=EditorPrefs.GetBool("ProjectCoal.AutoAlignTerrainTextures",true),generating=mm.IsGenerating()};
System.IO.File.WriteAllText(dir+"/after.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{terrains=records.Count,report.transformsUnchanged,report.auto,report.generating};
